{
  "$schema": "https://opencode.ai/config.json",
  "agent": {
    "code-reviewer": {
      "description": "Reviews code for best practices and potential issues",
      "mode": "subagent",
      "model": "anthropic/claude-sonnet-4-20250514",
      "temperature": 0.1,
      "prompt": "You are a code reviewer. Focus on security, performance, and maintainability.",
      "permission": {
        "edit": "deny",
        "write": "deny",
        "bash": "deny"
      }
    },
    "k8s-ops": {
      "description": "[[wiki/22-实体/02-K8s核心组件/kubernetes.md|kubernetes]] operations specialist for cluster management",
      "mode": "subagent",
      "model": "anthropic/claude-sonnet-4-20250514",
      "prompt": "{file:./prompts/k8s-ops.txt}",
      "steps": 20,
      "permission": {
        "bash": {
          "*": "ask",
          "kubectl *": "allow",
          "helm *": "allow",
          "rm *": "deny"
        }
      }
    },
    "fast-planner": {
      "description": "Quick planning with a fast model",
      "mode": "primary",
      "model": "anthropic/claude-haiku-4-20250514",
      "temperature": 0.1,
      "permission": {
        "edit": "deny",
        "write": "deny",
        "bash": "deny"
      }
    }
  }
}

{
  "agent": {
    "quick-fix": {
      "description": "Fast bug fixes with limited iterations",
      "mode": "subagent",
      "steps": 5,
      "prompt": "You are a quick fixer. Solve problems with minimal steps."
    }
  }
}

{
  "agent": {
    "security-audit": {
      "description": "Security-focused code analysis",
      "mode": "subagent",
      "model": "openai/o3",
      "temperature": 0.0,
      "prompt": "You are a security auditor. Focus on OWASP Top 10, injection vulnerabilities, authentication flaws, and sensitive data exposure. Never modify code.",
      "permission": {
        "edit": "deny",
        "write": "deny",
        "bash": "deny"
      }
    }
  }
}

{
  "agent": {
    "doc-writer": {
      "description": "Generate and update documentation",
      "mode": "subagent",
      "model": "anthropic/claude-sonnet-4-20250514",
      "temperature": 0.5,
      "prompt": "You are a technical writer. Generate clear, comprehensive documentation. Follow JSDoc/TSDoc conventions.",
      "permission": {
        "edit": { "*.md": "allow", "*.mdx": "allow", "*": "deny" },
        "bash": "deny"
      }
    }
  }
}
